import 'package:flutter/material.dart';
class AnimatedButton extends StatefulWidget { const AnimatedButton({required this.label, required this.onPressed, this.icon, super.key}); final String label; final VoidCallback onPressed; final IconData? icon; @override State<AnimatedButton> createState() => _AnimatedButtonState(); }
class _AnimatedButtonState extends State<AnimatedButton> { bool down = false; @override Widget build(BuildContext context) => GestureDetector(onTapDown: (_) => setState(() => down = true), onTapCancel: () => setState(() => down = false), onTapUp: (_) { setState(() => down = false); widget.onPressed(); }, child: AnimatedScale(duration: const Duration(milliseconds: 140), scale: down ? .96 : 1, child: FilledButton.icon(onPressed: widget.onPressed, icon: Icon(widget.icon ?? Icons.flash_on), label: Text(widget.label)))); }
